            <Text
              style={[
                styles.tabText,
                selectedTab === "challenges" && styles.activeTabText,
              ]}
            >
              AI Challenges
            </Text>
          </TouchableOpacity>
          <TouchableOpacity
            style={[
              styles.tab,
              selectedTab === "leaderboard" && styles.activeTab,
            ]}
            onPress={() => setSelectedTab("leaderboard")}
          >
            <Text
              style={[
                styles.tabText,
                selectedTab === "leaderboard" && styles.activeTabText,
