                  name="auto-awesome"
                  size={14}
                  color={COLORS.primary}
                />
                <Text style={styles.aiIndicatorText}>AI Curated</Text>
              </View>
            </View>

            {exploriaChallenges.map((challenge, index) => (
              <TouchableOpacity key={index} style={styles.challengeCard}>
                <View style={styles.challengeHeader}>
                  <View style={styles.challengeIcon}>
                    <MaterialIcons
                      name={challenge.icon as any}
                      size={16}
                      color={COLORS.primary}
                    />
                  </View>
                  <View style={styles.challengeInfo}>
                    <Text style={styles.challengeTitle}>{challenge.title}</Text>
                    <Text style={styles.challengeDescription}>
                      {challenge.description}
                    </Text>
                    <Text style={styles.challengeReward}>
                      🏆 {challenge.reward}
                    </Text>
                    <Text style={styles.challengePoints}>
                      {challenge.points} XP
                    </Text>
                  </View>
                  <Text style={styles.challengeProgress}>
                    {challenge.progress}%
                  </Text>
                </View>
                <View style={styles.challengeProgressBar}>
                  <View
                    style={[
                      styles.challengeProgressFill,
                      { width: `${challenge.progress}%` },
                    ]}
                  />
                </View>
              </TouchableOpacity>
            ))}
          </View>
        )}

        {/* Recent Achievements */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Recent Achievements</Text>
          <View style={styles.achievementsGrid}>
            {recentAchievements.map((achievement, index) => (
              <View key={index} style={styles.achievementCard}>
                <View style={styles.achievementIcon}>
                  <MaterialIcons
                    name={achievement.icon as any}
                    size={16}
                    color={COLORS.yellow500}
                  />
                </View>
                <Text style={styles.achievementTitle}>{achievement.title}</Text>
                <Text style={styles.achievementDate}>{achievement.earned}</Text>
              </View>
            ))}
          </View>
        </View>

        {/* Statistics */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Your Stats</Text>
          <View style={styles.statsGrid}>
            <View style={styles.statCard}>
              <Text style={styles.statNumber}>24</Text>
              <Text style={styles.statLabel}>Countries</Text>
            </View>
            <View style={styles.statCard}>
              <Text style={styles.statNumber}>89</Text>
              <Text style={styles.statLabel}>Trips</Text>
            </View>
            <View style={styles.statCard}>
              <Text style={styles.statNumber}>48</Text>
              <Text style={styles.statLabel}>Badges</Text>
            </View>
          </View>
        </View>

        {/* Leaderboard Preview */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Global Leaderboard</Text>
          {[
            {
              name: "Alex Thompson (You)",
              points: 1250,
              rank: 1,
              isUser: true,
            },
            { name: "Sarah Johnson", points: 1180, rank: 2, isUser: false },
            { name: "Mike Chen", points: 1050, rank: 3, isUser: false },
          ].map((user, index) => (
            <View
              key={index}
              style={[
                styles.leaderboardItem,
                user.isUser && styles.userLeaderboardItem,
              ]}
            >
              <View style={styles.leaderboardLeft}>
                <View
                  style={[
                    styles.rankBadge,
                    user.isUser && styles.userRankBadge,
                  ]}
                >
                  <Text
                    style={[
                      styles.rankText,
                      user.isUser && styles.userRankText,
                    ]}
                  >
                    #{user.rank}
                  </Text>
                </View>
                <Text
                  style={[
                    styles.leaderboardName,
                    user.isUser && styles.userLeaderboardName,
                  ]}
                >
                  {user.name}
                </Text>
              </View>
              <Text
                style={[
                  styles.leaderboardPoints,
                  user.isUser && styles.userLeaderboardPoints,
                ]}
              >
                {user.points} pts
              </Text>
            </View>
          ))}
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

